-- Desafios de Montagem: os desafios antigos saem e entram os cinco de "vestir a cena" (pedido da dona, 26/11/2026).
--
-- 1) RETIRAR os atuais: todo desafio de montagem (linha sem série; as com série são os capítulos FLAIR 3D, que o CBC já
--    não abre) volta a DRAFT. DRAFT some da lista e do detalhe para quem não é admin, mas a linha continua: as entregas
--    (flair_challenge_submissions, FK com ON DELETE CASCADE), as cartas guardadas como memória (locked_challenge_id), o
--    extrato de pontos e os selos ficam íntegros. Nada é apagado; um admin pode reativar um desafio pela administração.
--    O grupo "Lenda do estilo" fica sem desafios visíveis e por isso some da lista (FlairChallengeService.groupViews).
UPDATE flair_challenges SET status = 'DRAFT', version = version + 1, updated_at = '2026-11-26 12:00:00', last_modified_by = 'V110'
WHERE series IS NULL AND status <> 'DRAFT' AND slug NOT IN ('gala-na-piscina', 'noite-da-jaqueta-college', 'atelie-do-futuro', 'show-no-galpao', 'praca-dos-jacarandas');

-- 2) INSERIR os cinco novos. A cena é a imagem ANTES (public/flair/desafios/<scenario>/antes.webp); cada vaga é um
--    personagem, da esquerda para a direita, e só fecha com a carta da roupa dele (accepts: subcategoria e cor da peça,
--    conferidos em /check por CbcRules.misses). Os recortes vêm de scripts/flair/vestir_mascaras.py.
INSERT INTO flair_challenges (id, slug, name, names_json, description, descriptions_json, scenario, difficulty, status, moment_id, slots_json, requirements_json, theme_tags, points, repeat_limit, group_code, locks_cards, official, sort_order, version, created_at, updated_at) VALUES
('7e000000-0000-4000-8000-000000000001','gala-na-piscina','Gala à beira da piscina','{"pt-BR":"Gala à beira da piscina","en":"Poolside gala","es":"Gala junto a la piscina"}','Quatro modelos de regata e calça na passarela do pôr do sol. Cada carta certa veste uma delas com o vestido de alta-costura que é só dela.','{"pt-BR":"Quatro modelos de regata e calça na passarela do pôr do sol. Cada carta certa veste uma delas com o vestido de alta-costura que é só dela.","en":"Four models in tank tops and trousers on the sunset runway. Each right card dresses one of them in the couture gown that is hers alone.","es":"Cuatro modelos de camiseta de tirantes y pantalón en la pasarela del atardecer. Cada carta correcta viste a una con el vestido de alta costura que es solo suyo."}','vestir-piscina','MEDIUM','ACTIVE',NULL,'[{"key":"creme","position":"VES","accepts":{"subcategory":["dress"],"color":["cream","off_white","ivory","white"]},"label":{"pt-BR":"Vestido creme drapeado","en":"Draped cream gown","es":"Vestido crema drapeado"},"story":{"pt-BR":"A primeira modelo surge no vestido longo creme, drapeado num ombro só, com babado em cascata e o selo FAI no peito.","en":"The first model appears in the long cream gown, draped over one shoulder, with a cascading ruffle and the FAI seal on the chest.","es":"La primera modelo aparece con el vestido largo crema, drapeado en un solo hombro, con volante en cascada y el sello FAI en el pecho."}},{"key":"cobre","position":"VES","accepts":{"subcategory":["dress"],"color":["orange","rust","terracotta","amber"]},"label":{"pt-BR":"Vestido cobre plissado","en":"Pleated copper gown","es":"Vestido cobre plisado"},"story":{"pt-BR":"A segunda veste o vestido cobre plissado, com faixa cruzada no busto, fenda e camadas que brilham com o sol.","en":"The second wears the pleated copper gown, with a sash across the bust, a slit and layers that glow in the sun.","es":"La segunda viste el vestido cobre plisado, con banda cruzada en el busto, abertura y capas que brillan con el sol."}},{"key":"noite","position":"VES","accepts":{"subcategory":["dress"],"color":["black","charcoal"]},"label":{"pt-BR":"Vestido preto drapeado com fenda","en":"Black draped gown with slit","es":"Vestido negro drapeado con abertura"},"story":{"pt-BR":"A terceira fecha a gola alta do vestido preto drapeado, de ombro estruturado e fenda funda.","en":"The third closes the high collar of the black draped gown, with a structured shoulder and a deep slit.","es":"La tercera cierra el cuello alto del vestido negro drapeado, de hombro estructurado y abertura profunda."}},{"key":"petroleo","position":"VES","accepts":{"subcategory":["dress"],"color":["teal","blue"]},"label":{"pt-BR":"Vestido azul-petróleo com babados","en":"Teal ruffled gown","es":"Vestido azul petróleo con volantes"},"story":{"pt-BR":"A quarta fecha o desfile no vestido azul-petróleo de um ombro só, todo em babados e com fenda.","en":"The fourth closes the show in the one-shoulder teal gown, all ruffles, with a slit.","es":"La cuarta cierra el desfile con el vestido azul petróleo de un solo hombro, todo en volantes y con abertura."}}]','[]',NULL,35,1,NULL,TRUE,TRUE,10,0,'2026-11-26 12:00:00','2026-11-26 12:00:00'),
('7e000000-0000-4000-8000-000000000002','noite-da-jaqueta-college','Noite da jaqueta college','{"pt-BR":"Noite da jaqueta college","en":"Varsity jacket night","es":"Noche de la chaqueta universitaria"}','Na arena com tochas e fogos, quatro amigos de camiseta. Cada carta certa veste um deles com a jaqueta college dele, de ribanas listradas e selo FAI.','{"pt-BR":"Na arena com tochas e fogos, quatro amigos de camiseta. Cada carta certa veste um deles com a jaqueta college dele, de ribanas listradas e selo FAI.","en":"In the arena with torches and fireworks, four friends in T-shirts. Each right card dresses one of them in his or her varsity jacket, with striped ribbing and the FAI seal.","es":"En la arena con antorchas y fuegos, cuatro amigos en camiseta. Cada carta correcta viste a uno con su chaqueta universitaria, de puños a rayas y sello FAI."}','vestir-arena','EASY','ACTIVE',NULL,'[{"key":"preta","position":"SUP","accepts":{"subcategory":["jacket"],"color":["black","charcoal"]},"label":{"pt-BR":"Jaqueta college preta","en":"Black varsity jacket","es":"Chaqueta universitaria negra"},"story":{"pt-BR":"O primeiro cruza os braços na jaqueta college preta, botões de pressão e ribanas brancas listradas.","en":"The first crosses his arms in the black varsity jacket, snap buttons and white striped ribbing.","es":"El primero cruza los brazos con la chaqueta universitaria negra, botones de presión y puños blancos a rayas."}},{"key":"laranja","position":"SUP","accepts":{"subcategory":["jacket"],"color":["orange","rust","terracotta"]},"label":{"pt-BR":"Jaqueta college laranja","en":"Orange varsity jacket","es":"Chaqueta universitaria naranja"},"story":{"pt-BR":"A segunda sorri na jaqueta college laranja, de bolsos com vivo branco e ribanas listradas.","en":"The second smiles in the orange varsity jacket, with white-piped pockets and striped ribbing.","es":"La segunda sonríe con la chaqueta universitaria naranja, bolsillos con vivo blanco y puños a rayas."}},{"key":"creme","position":"SUP","accepts":{"subcategory":["jacket"],"color":["cream","off_white","ivory","white"]},"label":{"pt-BR":"Jaqueta college creme","en":"Cream varsity jacket","es":"Chaqueta universitaria crema"},"story":{"pt-BR":"O terceiro aparece na jaqueta college creme, gola e barra em preto e branco.","en":"The third appears in the cream varsity jacket, collar and hem in black and white.","es":"El tercero aparece con la chaqueta universitaria crema, cuello y bajo en negro y blanco."}},{"key":"vinho","position":"SUP","accepts":{"subcategory":["jacket"],"color":["burgundy","maroon","red"]},"label":{"pt-BR":"Jaqueta college vinho","en":"Burgundy varsity jacket","es":"Chaqueta universitaria burdeos"},"story":{"pt-BR":"A quarta põe a mão na cintura na jaqueta college vinho, de ribanas listradas.","en":"The fourth puts a hand on her hip in the burgundy varsity jacket with striped ribbing.","es":"La cuarta pone la mano en la cintura con la chaqueta universitaria burdeos de puños a rayas."}}]','[]',NULL,25,1,NULL,TRUE,TRUE,20,0,'2026-11-26 12:00:00','2026-11-26 12:00:00'),
('7e000000-0000-4000-8000-000000000003','atelie-do-futuro','Ateliê do futuro','{"pt-BR":"Ateliê do futuro","en":"Studio of the future","es":"Taller del futuro"}','No ateliê futurista, quatro costureiros de camiseta e calça. Cada carta certa veste um deles com a peça luminosa azul e dourada que é dele.','{"pt-BR":"No ateliê futurista, quatro costureiros de camiseta e calça. Cada carta certa veste um deles com a peça luminosa azul e dourada que é dele.","en":"In the futuristic studio, four tailors in T-shirts and trousers. Each right card dresses one of them in the glowing blue-and-gold piece that is theirs.","es":"En el taller futurista, cuatro sastres en camiseta y pantalón. Cada carta correcta viste a uno con la prenda luminosa azul y dorada que es suya."}','vestir-atelie','HARD','ACTIVE',NULL,'[{"key":"vestido","position":"VES","accepts":{"subcategory":["dress"],"color":["teal","blue","gold"]},"label":{"pt-BR":"Vestido longo azul e dourado","en":"Long blue-and-gold gown","es":"Vestido largo azul y dorado"},"story":{"pt-BR":"A primeira cruza os braços no vestido longo frente-única azul, riscado de fios dourados que brilham.","en":"The first crosses her arms in the long blue halter gown, streaked with glowing gold threads.","es":"La primera cruza los brazos con el vestido largo azul de cuello halter, surcado de hilos dorados que brillan."}},{"key":"bomber","position":"SUP","accepts":{"subcategory":["jacket"],"color":["teal","blue","gold"]},"label":{"pt-BR":"Jaqueta bomber azul e dourada","en":"Blue-and-gold bomber jacket","es":"Chaqueta bomber azul y dorada"},"story":{"pt-BR":"O segundo põe as mãos nos bolsos da jaqueta bomber azul com raios dourados e selo FAI.","en":"The second puts his hands in the pockets of the blue bomber jacket with gold rays and the FAI seal.","es":"El segundo mete las manos en los bolsillos de la chaqueta bomber azul con rayos dorados y sello FAI."}},{"key":"colete","position":"SUP","accepts":{"subcategory":["vest"],"color":["teal","blue","gold"]},"label":{"pt-BR":"Colete azul e dourado","en":"Blue-and-gold waistcoat","es":"Chaleco azul y dorado"},"story":{"pt-BR":"A terceira fecha o colete azul de debrum dourado; a calça ganha frisos de luz.","en":"The third buttons the blue waistcoat with gold trim; her trousers gain streaks of light.","es":"La tercera cierra el chaleco azul de ribete dorado; el pantalón gana destellos de luz."}},{"key":"casaco","position":"SUP","accepts":{"subcategory":["coat"],"color":["teal","blue","gold"]},"label":{"pt-BR":"Casaco longo azul e dourado","en":"Long blue-and-gold coat","es":"Abrigo largo azul y dorado"},"story":{"pt-BR":"O quarto pensa no casaco longo azul de gola alta, com cascatas douradas até a barra.","en":"The fourth ponders in the long high-collared blue coat, with gold cascades down to the hem.","es":"El cuarto piensa con el abrigo largo azul de cuello alto, con cascadas doradas hasta el bajo."}}]','[]',NULL,40,1,NULL,TRUE,TRUE,30,0,'2026-11-26 12:00:00','2026-11-26 12:00:00'),
('7e000000-0000-4000-8000-000000000004','show-no-galpao','Show no galpão','{"pt-BR":"Show no galpão","en":"Warehouse gig","es":"Concierto en el galpón"}','A banda toca de camiseta no galpão roxo. Cada carta certa veste um músico com o figurino vermelho, preto e dourado do show — o vestido vermelho é da cantora.','{"pt-BR":"A banda toca de camiseta no galpão roxo. Cada carta certa veste um músico com o figurino vermelho, preto e dourado do show — o vestido vermelho é da cantora.","en":"The band plays in T-shirts in the purple warehouse. Each right card dresses one musician in the red, black and gold stage outfit — the red dress belongs to the singer.","es":"La banda toca en camiseta en el galpón morado. Cada carta correcta viste a un músico con el vestuario rojo, negro y dorado del concierto: el vestido rojo es de la cantante."}','vestir-show','HARD','ACTIVE',NULL,'[{"key":"guitarra","position":"SUP","accepts":{"subcategory":["jacket","blazer"],"color":["black","red"]},"label":{"pt-BR":"Casaco militar preto e vermelho","en":"Black-and-red military jacket","es":"Chaqueta militar negra y roja"},"story":{"pt-BR":"O guitarrista abre o solo no casaco militar preto, de lapelas vermelhas, dragonas e bordado dourado.","en":"The guitarist opens the solo in the black military jacket with red lapels, epaulettes and gold embroidery.","es":"El guitarrista abre el solo con la chaqueta militar negra, de solapas rojas, charreteras y bordado dorado."}},{"key":"voz","position":"VES","accepts":{"subcategory":["dress"],"color":["red","crimson","burgundy"]},"label":{"pt-BR":"Vestido vermelho com corset dourado","en":"Red dress with gold corset","es":"Vestido rojo con corsé dorado"},"story":{"pt-BR":"A cantora solta a voz no vestido vermelho de corset bordado a ouro, cinto de correntes e braçadeiras.","en":"The singer lets her voice go in the red dress with a gold-embroidered corset, chain belt and armbands.","es":"La cantante suelta la voz con el vestido rojo de corsé bordado en oro, cinturón de cadenas y brazaletes."}},{"key":"bateria","position":"SUP","accepts":{"subcategory":["vest"],"color":["red","burgundy","black"]},"label":{"pt-BR":"Colete xadrez vermelho","en":"Red plaid waistcoat","es":"Chaleco de cuadros rojo"},"story":{"pt-BR":"O baterista marca o tempo no colete xadrez vermelho sem mangas, de debrum preto e dourado.","en":"The drummer keeps time in the sleeveless red plaid waistcoat with black-and-gold trim.","es":"El baterista marca el ritmo con el chaleco de cuadros rojo sin mangas, de ribete negro y dorado."}},{"key":"baixo","position":"VES","accepts":{"subcategory":["jumpsuit","matching_set"],"color":["black","charcoal"]},"label":{"pt-BR":"Macacão preto e dourado","en":"Black-and-gold jumpsuit","es":"Mono negro y dorado"},"story":{"pt-BR":"A baixista entra no macacão preto de corset com frisos dourados, faixas vermelhas e polainas de braço.","en":"The bassist steps into the black corset jumpsuit with gold piping, red panels and arm warmers.","es":"La bajista entra con el mono negro de corsé con vivos dorados, paneles rojos y calentadores de brazo."}}]','[]',NULL,45,1,NULL,TRUE,TRUE,40,0,'2026-11-26 12:00:00','2026-11-26 12:00:00'),
('7e000000-0000-4000-8000-000000000005','praca-dos-jacarandas','Praça dos jacarandás','{"pt-BR":"Praça dos jacarandás","en":"Jacaranda square","es":"Plaza de los jacarandás"}','Quatro amigos passeiam de camiseta pela praça do bonde. Cada carta certa veste um deles com o moletom de capuz e zíper verde e creme que é dele.','{"pt-BR":"Quatro amigos passeiam de camiseta pela praça do bonde. Cada carta certa veste um deles com o moletom de capuz e zíper verde e creme que é dele.","en":"Four friends stroll in T-shirts across the tram square. Each right card dresses one of them in his or her green-and-cream zip hoodie.","es":"Cuatro amigos pasean en camiseta por la plaza del tranvía. Cada carta correcta viste a uno con su sudadera con capucha y cremallera verde y crema."}','vestir-praca','EASY','ACTIVE',NULL,'[{"key":"bicicleta","position":"SUP","accepts":{"subcategory":["hoodie"],"color":["green","forest_green"]},"label":{"pt-BR":"Moletom verde com faixa creme","en":"Green hoodie with cream band","es":"Sudadera verde con franja crema"},"story":{"pt-BR":"A ciclista pedala no moletom verde de capuz e zíper, com a faixa creme em V no peito.","en":"The cyclist rides in the green zip hoodie with the cream V band across the chest.","es":"La ciclista pedalea con la sudadera verde de capucha y cremallera, con la franja crema en V en el pecho."}},{"key":"mochila","position":"SUP","accepts":{"subcategory":["hoodie"],"color":["cream","off_white","white"]},"label":{"pt-BR":"Moletom creme com mangas verdes","en":"Cream hoodie with green sleeves","es":"Sudadera crema con mangas verdes"},"story":{"pt-BR":"O rapaz da mochila veste o moletom creme de capuz e zíper, com recortes verdes nos ombros.","en":"The young man with the backpack wears the cream zip hoodie with green panels on the shoulders.","es":"El chico de la mochila viste la sudadera crema de capucha y cremallera, con cortes verdes en los hombros."}},{"key":"sacola","position":"SUP","accepts":{"subcategory":["hoodie"],"color":["green","forest_green"]},"label":{"pt-BR":"Moletom verde","en":"Green hoodie","es":"Sudadera verde"},"story":{"pt-BR":"A amiga da sacola conversa no moletom verde de capuz e zíper, com vivo creme.","en":"The friend with the tote chats in the green zip hoodie with cream piping.","es":"La amiga de la bolsa conversa con la sudadera verde de capucha y cremallera, con vivo crema."}},{"key":"oculos","position":"SUP","accepts":{"subcategory":["hoodie"],"color":["cream","green"]},"label":{"pt-BR":"Moletom creme e verde em blocos","en":"Cream-and-green colour-block hoodie","es":"Sudadera crema y verde en bloques"},"story":{"pt-BR":"O rapaz de óculos fecha o passeio no moletom em blocos, creme em cima e verde embaixo.","en":"The young man in glasses ends the walk in the colour-block hoodie, cream on top and green below.","es":"El chico de gafas cierra el paseo con la sudadera en bloques, crema arriba y verde abajo."}}]','[]',NULL,25,1,NULL,TRUE,TRUE,50,0,'2026-11-26 12:00:00','2026-11-26 12:00:00');
